/* @lc app=leetcode id=2242 lang=kotlin */ class Solution { fun maximumScore(scores: IntArray, edges: Array<IntArray>): Int = scores.indices.map { ArrayList<Int>() }.also { nb -> edges.forEach { (a, b) -> nb[a].add(b).also { nb[b].add(a) } } }.map { l -> l.sortedByDescending { scores[it] }.take(3) }.let { top -> edges.maxOfOrNull { (a, b) -> top[a].flatMap { x -> top[b].map { y -> x to y } }.filter { (x, y) -> x != b && y != a && x != y }.maxOfOrNull { (x, y) -> scores[a] + scores[b] + scores[x] + scores[y] } ?: -1 } ?: -1 } }